/bin/bash -lc "python3 - <<'PY'
import json
for f in ['other','own']:
 print(f)
 for i,c in enumerate(json.load(open('round1/'+f+'.json'))['cases']):
  e=c['expect'].get('error',{})
  if 'column' in e:
   l=c['source'].split('\\n')[e['line']-1]; col=e['column']
   print(i,col,repr(l[max(0,col-5):col-1])+' | '+repr(l[col-1:col+14]))
PY"

